version.transform:
(
  $.(
    {
      "availability": $not($isNil(availability)) ? availability * $coalesce([availabilityWeight,1]) : 1,
      "availabilityWeight": $not($isNil(availability)) ? $coalesce([availabilityWeight,1]) : 1,
      "performance": $not($isNil(performance)) ? performance * $coalesce([performanceWeight,1]): 1,
      "performanceWeight": $not($isNil(performance)) ? $coalesce([performanceWeight,1]): 1,
      "quality": $not($isNil(quality)) ? quality * $coalesce([qualityWeight,1]): 1,
      "qualityWeight": $not($isNil(quality)) ? $coalesce([qualityWeight,1]) :1
    }
  ){
    "total": {
      "availability": $sum(availability) / $sum(availabilityWeight),
      "performance": $sum(performance) / $sum(performanceWeight),
      "quality": $sum(quality) / $sum(qualityWeight)
    }
  }
).total ~> | $ | {
  "oee": $reduce(
    [availability, performance, quality], 
    function($value, $acc) { $isNumber($value) ? $value * $coalesce([$acc,1]) : $acc }
  )
} |
